import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
    Cpu,
    Zap, 
    ShieldCheck, 
    Search,
    Terminal,
    X,
    Loader2,
    Activity,
    Database,
    Clock
} from 'lucide-react';
import ActionableAI from './ActionableAI';
import AlphaAgentOps from './AlphaAgentOps';
import { useAppStore } from '@/store/useAppStore';
import { useQuery } from '@tanstack/react-query';
import apiClient from '@/api/client';
import { useThemeClasses } from '@/hooks/useThemeClasses';

const formatUptime = (seconds: number): string => {
    const d = Math.floor(seconds / 86400);
    const h = Math.floor((seconds % 86400) / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    if (d > 0) return `${d}d ${h}h ${m}m`;
    if (h > 0) return `${h}h ${m}m`;
    return `${m}m`;
};

const AlphaAI = () => {
    const { radiusClass, btnClass, isModern } = useThemeClasses();
    const setActiveTab = useAppStore((s) => s.setActiveTab);
    const [activeMode, setActiveMode] = React.useState<'actionable' | 'ops'>('actionable');
    const [showTerminal, setShowTerminal] = React.useState(false);
    const [terminalInput, setTerminalInput] = React.useState('');
    const [terminalOutput, setTerminalOutput] = React.useState<string[]>(['Alpha AI Terminal v4.2 — Type "help" for commands']);
    const [isTerminalLoading, setIsTerminalLoading] = React.useState(false);

    const { data: healthData, isLoading: healthLoading } = useQuery({
        queryKey: ['system-health'],
        queryFn: async () => {
            const { data } = await apiClient.get('/health');
            return data;
        },
        refetchInterval: 30000,
        enabled: !!localStorage.getItem('token'),
    });

    const modes = [
        { 
            id: 'actionable', 
            name: 'Actionable Intel', 
            icon: Zap, 
            description: 'Strategic decision support & yield optimization',
            color: 'text-primary-400',
            bg: 'bg-primary-500/10'
        },
        { 
            id: 'ops', 
            name: 'Agent Operations', 
            icon: Cpu, 
            description: 'Autonomous execution & multi-agent orchestration',
            color: 'text-secondary-400',
            bg: 'bg-secondary-500/10'
        }
    ];

    const handleTerminalCommand = async (cmd: string) => {
        const trimmed = cmd.trim().toLowerCase();
        setTerminalOutput(prev => [...prev, `> ${cmd}`]);

        if (trimmed === 'help') {
            setTerminalOutput(prev => [...prev, 'Commands: help, status, health, agents, uptime, clear']);
        } else if (trimmed === 'status' || trimmed === 'health') {
            setIsTerminalLoading(true);
            try {
                const { data } = await apiClient.get('/health');
                const lines = [
                    `Status: ${data.status}`,
                    `Uptime: ${formatUptime(data.uptime)}`,
                    `Database: ${data.services?.database || 'unknown'}`,
                    `Cache: ${data.services?.cache || 'unknown'}`,
                    `Environment: ${data.environment}`,
                    `Checked: ${new Date(data.timestamp).toLocaleTimeString()}`
                ];
                setTerminalOutput(prev => [...prev, ...lines]);
            } catch {
                setTerminalOutput(prev => [...prev, 'Error: Unable to reach backend health endpoint']);
            }
            setIsTerminalLoading(false);
        } else if (trimmed === 'agents') {
            setIsTerminalLoading(true);
            try {
                const { data } = await apiClient.get('/ai/status');
                if (data.success && data.data?.agents) {
                    data.data.agents.forEach((a: { name: string; status: string }) => {
                        setTerminalOutput(prev => [...prev, `${a.name}: ${a.status}`]);
                    });
                } else {
                    setTerminalOutput(prev => [...prev, 'Agent status: 3 registered (Agent Zero, Crew AI, OpenClaw)']);
                }
            } catch {
                setTerminalOutput(prev => [...prev, 'Agent status endpoint unavailable — agents registered but status unknown']);
            }
            setIsTerminalLoading(false);
        } else if (trimmed === 'uptime') {
            if (healthData?.uptime) {
                setTerminalOutput(prev => [...prev, `System uptime: ${formatUptime(healthData.uptime)}`]);
            } else {
                setTerminalOutput(prev => [...prev, 'Uptime data unavailable — health endpoint not responding']);
            }
        } else if (trimmed === 'clear') {
            setTerminalOutput(['Alpha AI Terminal v4.2']);
        } else if (trimmed) {
            setTerminalOutput(prev => [...prev, `Unknown command: "${trimmed}". Type "help" for available commands.`]);
        }
        setTerminalInput('');
    };

    const systemStats = [
        { 
            label: 'System Uptime', 
            value: healthLoading ? '...' : (healthData?.uptime ? formatUptime(healthData.uptime) : 'N/A'), 
            icon: Clock, 
            trend: healthData?.status === 'healthy' ? 'Healthy' : 'Check' 
        },
        { 
            label: 'Database', 
            value: healthLoading ? '...' : (healthData?.services?.database || 'Unknown'), 
            icon: Database, 
            trend: healthData?.services?.database === 'connected' ? 'Online' : 'Offline' 
        },
        { 
            label: 'Cache Layer', 
            value: healthLoading ? '...' : (healthData?.services?.cache || 'Unknown'), 
            icon: ShieldCheck, 
            trend: healthData?.services?.cache === 'connected' ? 'Active' : 'Down' 
        },
        { 
            label: 'System Status', 
            value: healthLoading ? '...' : (healthData?.status || 'Unknown'), 
            icon: Activity, 
            trend: healthData?.environment || '—' 
        },
    ];

    return (
        <div className="min-h-screen bg-black text-white p-8 custom-scrollbar">
            {/* Top Navigation Bar */}
            <div className="flex items-center justify-between mb-12">
                <div className="flex items-center gap-6">
                    <div className="flex items-center gap-3">
                        <img src="/logo.png" alt="Logo" className="w-10 h-10 rounded-lg shadow-lg" />
                    </div>
                    <div className="h-8 w-px bg-white/10" />
                    <div className="flex gap-2">
                        {modes.map((mode) => (
                            <button
                                key={mode.id}
                                onClick={() => setActiveMode(mode.id as 'actionable' | 'ops')}
                                className={`px-6 py-2.5 ${btnClass} border text-xxs font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
                                    activeMode === mode.id
                                        ? 'bg-white/10 border-white/20 text-white shadow-xl'
                                        : 'bg-transparent border-transparent text-white/40 hover:text-white/60'
                                }`}
                            >
                                <mode.icon className={`w-4 h-4 ${activeMode === mode.id ? mode.color : 'text-white/20'}`} />
                                {mode.name}
                            </button>
                        ))}
                    </div>
                </div>

                <div className="flex items-center gap-4">
                    <div className={`flex items-center gap-2 px-4 py-2 bg-white/5 border border-white/10 ${radiusClass}`}>
                        <div className={`w-2 h-2 rounded-full animate-pulse ${healthData?.status === 'healthy' ? 'bg-green-500' : 'bg-yellow-500'}`} />
                        <span className="text-xxs font-black text-white/60 uppercase tracking-widest">
                            {healthData?.status === 'healthy' ? 'System Online' : healthLoading ? 'Checking...' : 'Status Unknown'}
                        </span>
                    </div>
                    <button
                        onClick={() => setShowTerminal(!showTerminal)}
                        className={`p-2.5 border ${radiusClass} transition-all ${showTerminal ? 'bg-primary-500/20 border-primary-500/30 text-primary-400' : 'bg-white/5 border-white/10 text-white/60 hover:text-white'}`}
                    >
                        <Terminal className="w-5 h-5" />
                    </button>
                </div>
            </div>

            {/* Terminal Panel */}
            <AnimatePresence>
                {showTerminal && (
                    <motion.div
                        initial={{ height: 0, opacity: 0 }}
                        animate={{ height: 'auto', opacity: 1 }}
                        exit={{ height: 0, opacity: 0 }}
                        className={`mb-8 bg-black/60 border border-white/10 ${radiusClass} overflow-hidden`}
                    >
                        <div className="p-3 border-b border-white/5 flex items-center justify-between">
                            <span className="text-micro font-black text-white/40 uppercase tracking-widest">Terminal</span>
                            <button onClick={() => setShowTerminal(false)} className="text-white/40 hover:text-white">
                                <X className="w-3 h-3" />
                            </button>
                        </div>
                        <div className="p-3 max-h-40 overflow-y-auto font-mono text-xxs space-y-1">
                            {terminalOutput.map((line, i) => (
                                <div key={i} className={line.startsWith('>') ? 'text-primary-400' : 'text-white/60'}>
                                    {line}
                                </div>
                            ))}
                            {isTerminalLoading && (
                                <div className="flex items-center gap-2 text-white/40">
                                    <Loader2 className="w-3 h-3 animate-spin" />
                                    <span>Fetching...</span>
                                </div>
                            )}
                        </div>
                        <div className="p-2 border-t border-white/5">
                            <input
                                type="text"
                                value={terminalInput}
                                onChange={(e) => setTerminalInput(e.target.value)}
                                onKeyDown={(e) => { if (e.key === 'Enter') handleTerminalCommand(terminalInput); }}
                                placeholder="Type a command (help, status, agents, uptime, clear)..."
                                className="w-full bg-transparent text-white/80 text-xxs font-mono outline-none placeholder-white/20 px-2"
                            />
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Real System Health Stats */}
            <div className="grid grid-cols-4 gap-4 mb-12">
                {systemStats.map((stat, i) => (
                    <div key={i} className={`p-6 bg-white/5 border border-white/5 ${radiusClass} group hover:border-white/10 transition-all cursor-default relative overflow-hidden`}>
                        <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
                            <stat.icon className="w-12 h-12" />
                        </div>
                        <div className="flex items-center justify-between mb-2">
                            <span className="text-micro font-black text-white/40 uppercase tracking-widest">{stat.label}</span>
                            <span className={`text-micro font-bold uppercase ${
                                stat.trend === 'Healthy' || stat.trend === 'Online' || stat.trend === 'Active' 
                                    ? 'text-green-400' 
                                    : stat.trend === 'Check' || stat.trend === 'Offline' || stat.trend === 'Down'
                                        ? 'text-orange-400'
                                        : 'text-white/40'
                            }`}>{stat.trend}</span>
                        </div>
                        <div className="text-xl font-black">{stat.value}</div>
                    </div>
                ))}
            </div>

            {/* Dynamic Content Area */}
            <AnimatePresence mode="wait">
                <motion.div
                    key={activeMode}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    transition={{ duration: 0.4, ease: "easeOut" }}
                >
                    {activeMode === 'actionable' ? <ActionableAI /> : <AlphaAgentOps />}
                </motion.div>
            </AnimatePresence>

            {/* Global Footer Quick Controls */}
            <div className="fixed bottom-8 right-8 z-50">
                <button
                    onClick={() => setActiveTab('knowledge')}
                    className={`p-5 bg-primary-500 ${radiusClass} shadow-2xl shadow-primary-500/40 text-black hover:bg-primary-400 hover:scale-105 active:scale-95 transition-all outline outline-8 outline-primary-500/10`}
                >
                    <Search className="w-6 h-6 stroke-[3]" />
                </button>
            </div>
        </div>
    );
};

export default AlphaAI;

import React from 'react';
import { Farmer, Visit } from '@/types/dashboard';
import { Button } from './ui/Button';
import { Input } from './ui/Input';
import { Select } from './ui/Select';
import { Badge } from './ui/Badge';
import { motion, AnimatePresence } from 'framer-motion';
import { FarmerDetailHeader } from './FarmerDetailHeader';
import { FarmerYieldChart } from './FarmerYieldChart';
import { FarmerVisitTimeline } from './FarmerVisitTimeline';
import {
    X,
    TrendingUp,
    MessageSquare,
    Phone,
    Video,
    Clock,
    ChevronRight,
    Sprout,
    Activity,
    Mail,
    History,
    FileText,
    Loader2
} from 'lucide-react';
import { VideoCall } from './VideoCall';
import { useLanguage } from '@/lib/LanguageContext';
import { useAppStore } from '@/store/useAppStore';
import { useNavigate } from 'react-router-dom';
import { useThemeClasses } from '@/hooks/useThemeClasses';

import { fetchSMSHistory } from '@/api/smsService';
import { generateSynthesis } from '@/api/chatbotService';
import { fetchPriorityScore, updateVisit } from '@/api/visitService';
import { SatelliteInsights } from './SatelliteInsights';
import { ConfirmModal } from './ConfirmModal';

interface FarmerDetailPanelProps {
    isOpen: boolean;
    onClose: () => void;
    farmer: Farmer | null;
    visits?: Visit[];
}


export const FarmerDetailPanel: React.FC<FarmerDetailPanelProps> = ({
    isOpen,
    onClose,
    farmer,
    visits = []
}) => {
    const { t } = useLanguage();
    const { 
        setActiveTab: setGlobalTab, 
        themeName, 
        addNotification, 
        setPendingSMS, 
        updateFarmer,
        user: storeUser,
        showContextMenu,
        showShareModal
    } = useAppStore();

    const { radiusClass, btnClass, isModern } = useThemeClasses();
    const isCyber = themeName === 'cyber' && isModern;
    const navigate = useNavigate();

    const [activeTab, setActiveTab] = React.useState<'overview' | 'history' | 'insights'>('overview');
    const [isEditing, setIsEditing] = React.useState(false);
    const [editData, setEditData] = React.useState<Farmer>(farmer!);
    const [interactions, setInteractions] = React.useState<{ id?: string; type: string; date: string; status: string; content: string; duration?: string }[]>([]);
    const [isLoadingHistory, setIsLoadingHistory] = React.useState(false);
    const [showVideoCall, setShowVideoCall] = React.useState(false);
    const [isSynthesizing, setIsSynthesizing] = React.useState(false);
    const [isRefreshingPriority, setIsRefreshingPriority] = React.useState(false);
    const [isDeleteModalOpen, setIsDeleteModalOpen] = React.useState(false);
    const [localVisits, setLocalVisits] = React.useState(visits);

    React.useEffect(() => {
        setLocalVisits(visits);
    }, [visits]);

    const loadInteractions = React.useCallback(async () => {
        if (!farmer?.id) return;
        setIsLoadingHistory(true);
        try {
            const res = await fetchSMSHistory(farmer.id);
            if (res.success) {
                setInteractions(res.data.map((msg) => ({
                    id: msg.id,
                    type: 'SMS',
                    date: new Date(msg.created_at).toLocaleDateString(),
                    status: msg.status === 'sent' ? 'delivered' : msg.status,
                    content: msg.message
                })));
            }
        } catch (err) {
            console.error('Failed to load interactions:', err);
        } finally {
            setIsLoadingHistory(false);
        }
    }, [farmer?.id]);

    React.useEffect(() => {
        if (farmer) setEditData(farmer);
        if (activeTab === 'history') {
            loadInteractions();
        }
    }, [farmer, activeTab, loadInteractions]);

    const handleSave = () => {
        if (!farmer) return;
        updateFarmer(farmer.id, editData);
        setIsEditing(false);
        addNotification({
            type: 'success',
            message: `Updated profile for ${farmer.firstName}`
        });
    };

    const handleShare = () => {
        if (!farmer) return;
        showShareModal({
            entityType: 'farmer',
            entityId: farmer.id,
            entityName: `${farmer.firstName} ${farmer.lastName}`
        });
    };

    const handleContextMenu = (e: React.MouseEvent) => {
        if (!farmer) return;
        e.preventDefault();
        showContextMenu({
            x: e.clientX,
            y: e.clientY,
            entityType: 'farmer',
            entityId: farmer.id
        });
    };

    if (!farmer) return null;

    const handleAction = (type: 'chat' | 'sms' | 'call' | 'video') => {
        switch (type) {
            case 'chat':
                setGlobalTab('farmerchat');
                onClose();
                break;
            case 'sms':
                if (farmer) {
                    setPendingSMS({ phone: farmer.phone || '', name: `${farmer.firstName || ''} ${farmer.lastName || ''}` });
                    navigate('/sms');
                }
                break;
            case 'call':
                if (farmer.phone) {
                    window.location.href = `tel:${farmer.phone}`;
                    addNotification({
                        type: 'info',
                        message: `${t('action_connecting') || 'Connecting to'} ${farmer.firstName}...`
                    });
                } else {
                    addNotification({ type: 'error', message: 'No phone number available' });
                }
                break;
            case 'video':
                setShowVideoCall(true);
                break;
        }
    };

    const handleStartSynthesis = async () => {
        if (!farmer?.id) return;

        setIsSynthesizing(true);
        try {
            const res = await generateSynthesis({
                farmerId: farmer.id,
                notes: `Farmer: ${farmer.firstName} ${farmer.lastName}. Region: ${farmer.region}. Farm Size: ${farmer.farmSize}ha. Crops: ${farmer.crops?.join(', ')}.`,
                visitDate: new Date().toLocaleDateString()
            });

            if (res.success) {
                addNotification({
                    type: 'success',
                    message: `AI Synthesis complete for ${farmer.firstName}`
                });
            }
        } catch (err) {
            console.error('Synthesis failed:', err);
            addNotification({
                type: 'error',
                message: 'AI Synthesis failed to generate'
            });
        } finally {
            setIsSynthesizing(false);
        }
    };

    const handleRefreshPriority = async () => {
        if (!farmer?.id) return;
        setIsRefreshingPriority(true);
        try {
            const res = await fetchPriorityScore(farmer.id);
            if (res.success) {
                addNotification({
                    type: 'success',
                    message: `Priority: ${res.data.level.toUpperCase()} (score: ${res.data.score}/100) — ${res.data.recommendedAction}`
                });
                // Switch to insights tab to show the updated data
                setActiveTab('insights');
            }
        } catch {
            addNotification({
                type: 'error',
                message: 'Failed to refresh priority analysis'
            });
        } finally {
            setIsRefreshingPriority(false);
        }
    };

    const handleUpdateVisitStatus = async (visitId: string, status: 'completed' | 'cancelled') => {
        try {
            const res = await updateVisit(visitId, { status });
            if (res.success) {
                setLocalVisits(prev => prev.map(v => v.id === visitId ? { ...v, status } : v));
                addNotification({
                    type: 'success',
                    message: `Visit marked as ${status}`
                });
            }
        } catch (err) {
            console.error('Failed to update visit status:', err);
            addNotification({
                type: 'error',
                message: `Failed to mark visit as ${status}`
            });
        }
    };

    const nextScheduledVisit = localVisits
        .filter(v => v.status === 'scheduled')
        .sort((a, b) => new Date(a.scheduled_at).getTime() - new Date(b.scheduled_at).getTime())[0];

    return (
        <AnimatePresence>
            {isOpen && (
                <>
                    {/* Backdrop */}
                    <motion.div
                        key="panel-backdrop"
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={onClose}
                        className="fixed inset-0 bg-black/40 backdrop-blur-sm z-[60]"
                    />

                    {/* Panel */}
                    <motion.aside
                        key="panel-content"
                        initial={{ x: '100%' }}
                        animate={{ x: 0 }}
                        exit={{ x: '100%' }}
                        transition={{ type: 'spring', damping: 25, stiffness: 200 }}
                        className={`fixed right-0 top-0 bottom-0 w-full max-w-xl z-[70] shadow-2xl overflow-hidden flex flex-col ${isCyber ? 'bg-black/90 dark:bg-gray-900/90' : 'bg-white/90 dark:bg-gray-900/90'} backdrop-blur-xl border-l border-white/20 dark:border-gray-800/50`}
                        style={{ borderTopLeftRadius: 'var(--radius-card)', borderBottomLeftRadius: 'var(--radius-card)' }}
                    >
                        {/* Header Section */}
                        <FarmerDetailHeader
                            farmer={farmer}
                            editData={editData}
                            setEditData={setEditData}
                            isEditing={isEditing}
                            setIsEditing={setIsEditing}
                            handleSave={handleSave}
                            handleShare={handleShare}
                            handleContextMenu={handleContextMenu}
                            setIsDeleteModalOpen={setIsDeleteModalOpen}
                            onClose={onClose}
                            radiusClass={radiusClass}
                            isCyber={isCyber}
                        />

                        {/* Tabs */}
                        <div className={`px-8 pt-6 border-b bg-white border-gray-100 dark:border-gray-800`}>
                            <div className="flex items-center gap-8">
                                {[
                                    { id: 'overview', label: t('nav_dashboard') || 'Overview', icon: FileText },
                                    { id: 'history', label: t('nav_sms_history') || 'Communication', icon: History },
                                    { id: 'insights', label: t('nav_analytics') || 'Insights', icon: TrendingUp },
                                ].map((tab) => (
                                    <button
                                        key={tab.id}
                                        onClick={() => setActiveTab(tab.id as 'overview' | 'history' | 'insights')}
                                        className={`pb-4 text-xxs font-black uppercase tracking-[0.2em] relative transition-all ${activeTab === tab.id
                                            ? (isCyber ? 'text-primary-400' : 'text-primary-600')
                                            : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'
                                            }`}
                                    >
                                        <span className="flex items-center gap-2">
                                            <tab.icon className="w-4 h-4" />
                                            {tab.label}
                                        </span>
                                        {activeTab === tab.id && (
                                            <motion.div
                                                layoutId="activeTab"
                                                className={`absolute bottom-0 left-0 right-0 h-1 rounded-t-full bg-primary-500`}
                                            />
                                        )}
                                    </button>
                                ))}
                            </div>
                        </div>

                        {/* Content Section */}
                        <div className="flex-1 overflow-y-auto p-8 space-y-10 custom-scrollbar overflow-x-hidden">
                            {activeTab === 'overview' ? (
                                <>
                                    {/* Action Buttons */}
                                    <div className="grid grid-cols-4 gap-4">
                                        {[
                                            { id: 'chat', icon: MessageSquare, label: t('action_chat'), color: isCyber ? 'bg-primary-500/10 border border-primary-500/20 text-primary-400' : 'bg-primary-500 text-white' },
                                            { id: 'sms', icon: Mail, label: t('action_sms'), color: isCyber ? 'bg-secondary-500/10 border border-secondary-500/20 text-secondary-400' : 'bg-secondary-500 text-white' },
                                            { id: 'call', icon: Phone, label: t('action_call'), color: isCyber ? 'bg-green-500/10 border border-green-500/20 text-green-400' : 'bg-green-500 text-white' },
                                            { id: 'video', icon: Video, label: t('action_video'), color: isCyber ? 'bg-purple-500/10 border border-purple-500/20 text-purple-400' : 'bg-purple-500 text-white' },
                                        ].map((action) => (
                                            <button
                                                key={action.id}
                                                onClick={() => handleAction(action.id as 'chat' | 'sms' | 'call' | 'video')}
                                                onContextMenu={(e) => {
                                                    e.preventDefault();
                                                    showContextMenu({ x: e.clientX, y: e.clientY, entityType: 'farmer', entityId: farmer.id });
                                                }}
                                                className="flex flex-col items-center gap-2 group"
                                            >
                                                <div className={`w-12 h-12 ${radiusClass} ${action.color} flex items-center justify-center shadow-lg transition-all group-hover:scale-110 group-hover:rotate-3 outline outline-4 outline-transparent hover:outline-white/20`}>
                                                    <action.icon className="w-6 h-6" />
                                                </div>
                                                <span className={`text-xxs font-black uppercase tracking-widest transition-colors ${isCyber ? 'text-primary-300' : 'text-gray-400 group-hover:text-gray-600 dark:group-hover:text-gray-200'}`}>
                                                    {action.label}
                                                </span>
                                            </button>
                                        ))}
                                    </div>

                                    {/* Yield Performance */}
                                    <FarmerYieldChart
                                        farmer={farmer}
                                        radiusClass={radiusClass}
                                    />

                                    <div className="grid grid-cols-2 gap-6">
                                        {/* Crops Section */}
                                        <section className={`p-6 ${radiusClass} border shadow-sm bg-theme-bg-card dark:bg-gray-800/80 border-gray-100 dark:border-gray-700`}>
                                            <h3 className={`text-xs font-black uppercase tracking-widest mb-4 flex items-center gap-2 text-gray-400`}>
                                                <Sprout className={`w-4 h-4 text-green-500`} />
                                                {t('table_crops')}
                                            </h3>
                                            {isEditing ? (
                                                <div className="space-y-2">
                                                    <div className="flex flex-wrap gap-2">
