                        </button>
                        <div className="overflow-y-auto max-h-[85vh]">
                            <VideoCall
                                roomId={`farmer-${farmer.id}`}
                                userId={(storeUser as unknown)?.userId || 'unknown'}
                                userName={`${storeUser?.firstName} ${storeUser?.lastName}` || 'Extension Officer'}
                                isHost={true}
                                onEnd={() => setShowVideoCall(false)}
                            />
                        </div>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    );
};

